interfaces.contract:
Filter = {"and": [Condition | Filter, ...]}; Condition = {"field": str, "op": "eq" | "ne" | "in" | "gte" | "lte", "value": Any}
FILTER_FIELDS = ("status", "verdict", "risk_tier", "producer", "assignee_role", "rework_count", "waits_for_person", "covers", "sprint_id")
parse_filter(raw) -> Filter, raising FilterRefused(field) for a field outside FILTER_FIELDS
